using UnityEngine;
using UnityEngine.InputSystem;
namespace FarmPrototype.Player { public sealed class FarmEquipmentController : MonoBehaviour { [SerializeField] GameObject hoe; [SerializeField] GameObject seeds; [SerializeField] GameObject wateringCan; void Start() { Select(hoe); var hand = FindBone("Hand_R"); if (hand == null) return; Attach(hoe, hand, new Vector3(0.05f,0f,0f), new Vector3(10f,90f,80f)); Attach(seeds, hand, Vector3.zero, new Vector3(0f,90f,0f)); Attach(wateringCan, hand, new Vector3(0.03f,0f,0f), new Vector3(0f,90f,70f)); } void Update() { var k=Keyboard.current; if(k==null)return; if(k.digit1Key.wasPressedThisFrame)Select(hoe); if(k.digit2Key.wasPressedThisFrame)Select(seeds); if(k.digit3Key.wasPressedThisFrame)Select(wateringCan); if(k.digit4Key.wasPressedThisFrame)Select(null); } void Select(GameObject item) { if(hoe)hoe.SetActive(item==hoe); if(seeds)seeds.SetActive(item==seeds); if(wateringCan)wateringCan.SetActive(item==wateringCan); } static void Attach(GameObject item,Transform hand,Vector3 pos,Vector3 rot) { if(!item)return; item.transform.SetParent(hand,false); item.transform.localPosition=pos; item.transform.localRotation=Quaternion.Euler(rot); } Transform FindBone(string name) { foreach(var bone in GetComponentsInChildren<Transform>(true)) if(bone.name==name)return bone; return null; } } }
